import{_ as l,a0 as n,w as p,s as r,I as t,x as s,ao as a,a1 as d,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Bash 中的 ＆ 符号和文件描述符 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 中的 ＆ 符号和文件描述符 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 中的 ＆ 符号和文件描述符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 中的 ＆ 符号和文件描述符 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190212 Ampersands and File Descriptors in Bash","title":"Bash 中的 ＆ 符号和文件描述符","tag":"201903","desc":""},"relativePath":"201903/20190212 Ampersands and File Descriptors in Bash.md","filePath":"[post].md"}'),c={name:"201903/20190212 Ampersands and File Descriptors in Bash.md"};function g(h,e,u,k,b,f){const i=n("Link");return p(),r("div",null,[e[31]||(e[31]=t("h1",{id:"bash-中的-符号和文件描述符",tabindex:"-1"},[s("Bash 中的 ＆ 符号和文件描述符 "),t("a",{class:"header-anchor",href:"#bash-中的-符号和文件描述符","aria-label":"Permalink to “Bash 中的 ＆ 符号和文件描述符”"},"​")],-1)),e[32]||(e[32]=t("blockquote",null,[t("p",null,"了解如何将 “＆” 与尖括号结合使用，并从命令行中获得更多信息。")],-1)),e[33]||(e[33]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ampersand-coffee.png?itok=yChaT-47",alt:""})],-1)),t("p",null,[e[1]||(e[1]=a("在我们探究大多数链式 Bash 命令中出现的所有的杂项符号（<code>&amp;</code>、<code>|</code>、<code>;</code>、<code>&gt;</code>、<code>&lt;</code>、<code>{</code>、<code>[</code>、<code>(</code>、<code>)</code>、<code>]</code>、<code>}</code> 等等）的任务中，",23)),d(i,{href:"https://linux.cn/article-10587-1.html"},{default:o(()=>[...e[0]||(e[0]=[s("我们一直在仔细研究 & 符号",-1)])]),_:1}),e[2]||(e[2]=s("。",-1))]),t("p",null,[d(i,{href:"https://linux.cn/article-10587-1.html"},{default:o(()=>[...e[3]||(e[3]=[s("上次，我们看到了如何使用 & 把可能需要很长时间运行的进程放到后台运行",-1)])]),_:1}),e[4]||(e[4]=s("。但是，",-1)),e[5]||(e[5]=t("code",null,"＆",-1)),e[6]||(e[6]=s(" 与尖括号 ",-1)),e[7]||(e[7]=t("code",null,"<",-1)),e[8]||(e[8]=s(" 结合使用，也可用于将输出或输出通过管道导向其他地方。",-1))]),t("p",null,[e[11]||(e[11]=s("在 ",-1)),d(i,{href:"https://linux.cn/article-10502-1.html"},{default:o(()=>[...e[9]||(e[9]=[s("前面的",-1)])]),_:1}),e[12]||(e[12]=s()),d(i,{href:"https://linux.cn/article-10529-1.html"},{default:o(()=>[...e[10]||(e[10]=[s("尖括号教程中",-1)])]),_:1}),e[13]||(e[13]=s("，你看到了如何使用 ",-1)),e[14]||(e[14]=t("code",null,">",-1)),e[15]||(e[15]=s("，如下：",-1))]),e[34]||(e[34]=a('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls &gt; list.txt</span></span></code></pre></div><p>将 <code>ls</code> 输出传递给 <code>list.txt</code> 文件。</p><p>现在我们看到的是简写：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls 1&gt; list.txt</span></span></code></pre></div><p>在这种情况下，<code>1</code> 是一个文件描述符，指向标准输出（<code>stdout</code>）。</p><p>以类似的方式，<code>2</code> 指向标准错误输出（<code>stderr</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls 2&gt; error.log</span></span></code></pre></div><p>所有错误消息都通过管道传递给 <code>error.log</code> 文件。</p><p>回顾一下：<code>1&gt;</code> 是标准输出（<code>stdout</code>），<code>2&gt;</code> 是标准错误输出（<code>stderr</code>）。</p><p>第三个标准文件描述符，<code>0&lt;</code> 是标准输入（<code>stdin</code>）。你可以看到它是一个输入，因为箭头（<code>&lt;</code>）指向<code>0</code>，而对于 <code>1</code> 和 <code>2</code>，箭头（<code>&gt;</code>）是指向外部的。</p><h3 id="标准文件描述符有什么用" tabindex="-1">标准文件描述符有什么用？ <a class="header-anchor" href="#标准文件描述符有什么用" aria-label="Permalink to “标准文件描述符有什么用？”">​</a></h3><p>如果你在阅读本系列以后，你已经多次使用标准输出（<code>1&gt;</code>）的简写形式：<code>&gt;</code>。</p><p>例如，当（假如）你知道你的命令会抛出一个错误时，像 <code>stderr</code>（<code>2</code>）这样的东西也很方便，但是 Bash 告诉你的东西是没有用的，你不需要看到它。如果要在 <code>home/</code> 目录中创建目录，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir newdir</span></span></code></pre></div><p>如果 <code>newdir/</code> 已经存在，<code>mkdir</code> 将显示错误。但你为什么要关心这些呢？（好吧，在某些情况下你可能会关心，但并非总是如此。）在一天结束时，<code>newdir</code> 会以某种方式让你填入一些东西。你可以通过将错误消息推入虚空（即 ``/dev/null`）来抑制错误消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir newdir 2&gt; /dev/null</span></span></code></pre></div><p>这不仅仅是 “让我们不要看到丑陋和无关的错误消息，因为它们很烦人”，因为在某些情况下，错误消息可能会在其他地方引起一连串错误。比如说，你想找到 <code>/etc</code> 下所有的 <code>.service</code> 文件。你可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot;</span></span></code></pre></div><p>但事实证明，在大多数系统中，<code>find</code> 显示的错误会有许多行，因为普通用户对 <code>/etc</code> 下的某些文件夹没有读取访问权限。它使读取正确的输出变得很麻烦，如果 <code>find</code> 是更大的脚本的一部分，它可能会导致行中的下一个命令排队。</p><p>相反，你可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 2&gt; /dev/null</span></span></code></pre></div><p>而且你只得到你想要的结果。</p><h3 id="文件描述符入门" tabindex="-1">文件描述符入门 <a class="header-anchor" href="#文件描述符入门" aria-label="Permalink to “文件描述符入门”">​</a></h3><p>单独的文件描述符 <code>stdout</code> 和 <code>stderr</code> 还有一些注意事项。如果要将输出存储在文件中，请执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 1&gt; services.txt</span></span></code></pre></div><p>工作正常，因为 <code>1&gt;</code> 意味着 “发送标准输出且自身标准输出（非标准错误）到某个地方”。</p><p>但这里存在一个问题：如果你想把命令抛出的错误信息记录到文件，而结果中没有错误信息你该怎么<strong>做</strong>？上面的命令并不会这样做，因为它只写入 <code>find</code> 正确的结果，而：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 2&gt; services.txt</span></span></code></pre></div><p>只会写入命令抛出的错误信息。</p><p>我们如何得到两者？请尝试以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; &amp;&gt; services.txt</span></span></code></pre></div><p>…… 再次和 <code>&amp;</code> 打个招呼！</p><p>我们一直在说 <code>stdin</code>（<code>0</code>）、<code>stdout</code>（<code>1</code>）和 <code>stderr</code>（<code>2</code>）是“文件描述符”。文件描述符是一种特殊构造，是指向文件的通道，用于读取或写入，或两者兼而有之。这来自于将所有内容都视为文件的旧 UNIX 理念。想写一个设备？将其视为文件。想写入套接字并通过网络发送数据？将其视为文件。想要读取和写入文件？嗯，显然，将其视为文件。</p><p>因此，在管理命令的输出和错误的位置时，将目标视为文件。因此，当你打开它们来读取和写入它们时，它们都会获得文件描述符。</p><p>这是一个有趣的效果。例如，你可以将内容从一个文件描述符传递到另一个文件描述符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 1&gt; services.txt 2&gt;&amp;1</span></span></code></pre></div><p>这会将 <code>stderr</code> 导向到 <code>stdout</code>，而 <code>stdout</code> 通过管道被导向到一个文件中 <code>services.txt</code> 中。</p><p>它再次出现：<code>&amp;</code> 发信号通知 Bash <code>1</code> 是目标文件描述符。</p><p>标准文件描述符的另一个问题是，当你从一个管道传输到另一个时，你执行此操作的顺序有点违反直觉。例如，按照上面的命令。它看起来像是错误的方式。你应该像这样阅读它：“将输出导向到文件，然后将错误导向到标准输出。” 看起来错误输出会在后面，并且在输出到标准输出（<code>1</code>）已经完成时才发送。</p><p>但这不是文件描述符的工作方式。文件描述符不是文件的占位符，而是文件的输入和（或）输出通道。在这种情况下，当你做 <code>1&gt; services.txt</code> 时，你的意思是 “打开一个写管道到 <code>services.txt</code> 并保持打开状态”。<code>1</code> 是你要使用的管道的名称，它将保持打开状态直到该行的结尾。</p><p>如果你仍然认为这是错误的方法，试试这个：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 2&gt;&amp;1 1&gt;services.txt</span></span></code></pre></div><p>并注意它是如何不工作的；注意错误是如何被导向到终端的，而只有非错误的输出（即 <code>stdout</code>）被推送到 <code>services.txt</code>。</p><p>这是因为 Bash 从左到右处理 <code>find</code> 的每个结果。这样想：当 Bash 到达 <code>2&gt;&amp;1</code> 时，<code>stdout</code> （<code>1</code>）仍然是指向终端的通道。如果 <code>find</code> 给 Bash 的结果包含一个错误，它将被弹出到 <code>2</code>，转移到 <code>1</code>，然后留在终端！</p><p>然后在命令结束时，Bash 看到你要打开 <code>stdout</code>（<code>1</code>） 作为到 <code>services.txt</code> 文件的通道。如果没有发生错误，结果将通过通道 <code>1</code> 进入文件。</p><p>相比之下，在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 1&gt;services.txt 2&gt;&amp;1</span></span></code></pre></div><p><code>1</code> 从一开始就指向 <code>services.txt</code>，因此任何弹出到 <code>2</code> 的内容都会导向到 <code>1</code> ，而 <code>1</code> 已经指向最终去的位置 <code>services.txt</code>，这就是它工作的原因。</p><p>在任何情况下，如上所述 <code>&amp;&gt;</code> 都是“标准输出和标准错误”的缩写，即 <code>2&gt;&amp;1</code>。</p><p>这可能有点多，但不用担心。重新导向文件描述符在 Bash 命令行和脚本中是司空见惯的事。随着本系列的深入，你将了解更多关于文件描述符的知识。下周见!</p><hr>',51)),t("p",null,[e[17]||(e[17]=s("via: ",-1)),d(i,{href:"https://www.linux.com/blog/learn/2019/2/ampersands-and-file-descriptors-bash"},{default:o(()=>[...e[16]||(e[16]=[s("https://www.linux.com/blog/learn/2019/2/ampersands-and-file-descriptors-bash",-1)])]),_:1})]),t("p",null,[e[22]||(e[22]=s("作者：",-1)),d(i,{href:"https://www.linux.com/users/bro66"},{default:o(()=>[...e[18]||(e[18]=[s("Paul Brown",-1)])]),_:1}),e[23]||(e[23]=s(" 选题：",-1)),d(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[19]||(e[19]=[s("lujun9972",-1)])]),_:1}),e[24]||(e[24]=s(" 译者：",-1)),d(i,{href:"https://github.com/zero-mk"},{default:o(()=>[...e[20]||(e[20]=[s("zero-mk",-1)])]),_:1}),e[25]||(e[25]=s(" 校对：",-1)),d(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[21]||(e[21]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[28]||(e[28]=s("本文由 ",-1)),d(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[26]||(e[26]=[s("LCTT",-1)])]),_:1}),e[29]||(e[29]=s(" 原创编译，",-1)),d(i,{href:"https://linux.cn/"},{default:o(()=>[...e[27]||(e[27]=[s("Linux中国",-1)])]),_:1}),e[30]||(e[30]=s(" 荣誉推出",-1))])])}const C=l(c,[["render",g]]);export{x as __pageData,C as default};
